void ck(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}
std::vector<double> load(const char*f){std::ifstream in(f,std::ios::binary|std::ios::ate);if(!in)exit(3);size_t n=in.tellg();if(n%8)exit(3);in.seekg(0);std::vector<double>v(n/8);in.read((char*)v.data(),n);if(!in)exit(3);return v;}
void append(std::vector<double>&a,double x){a.push_back(x);}void append(std::vector<double>&a,float x){a.push_back(x);}void append(std::vector<double>&a,int x){a.push_back(x);}void append(std::vector<double>&a,float4 x){a.insert(a.end(),{x.x,x.y,x.z,x.w});}void append(std::vector<double>&a,int2 x){a.insert(a.end(),{double(x.x),double(x.y)});}
template<class T>struct G{std::vector<T>h;T*base,*d;G(std::vector<T>v,T guard){h.assign(v.size()+128,guard);std::copy(v.begin(),v.end(),h.begin()+64);ck(cudaMalloc(&base,h.size()*sizeof(T)));d=base+64;reset();}void reset(){ck(cudaMemcpy(base,h.data(),h.size()*sizeof(T),cudaMemcpyHostToDevice));}void capture(std::vector<double>&a){std::vector<T>v(h.size());ck(cudaMemcpy(v.data(),base,v.size()*sizeof(T),cudaMemcpyDeviceToHost));for(T x:v)append(a,x);}~G(){cudaFree(base);}};
struct Case{int n,nt,reps;float3 period;G<float4>*co,*vel;G<int>*nb;G<int2>*bonds;G<double>*l0;std::vector<G<float>*>params;std::vector<G<double>*>force;};
int main(){auto pre=load(FIXTURE),gold=load(ORACLE);std::ifstream in(KINDS,std::ios::binary);std::vector<unsigned char>kind(gold.size());in.read((char*)kind.data(),kind.size());if(!in)return 3;size_t pos=1;std::vector<Case>cs;
 for(int ci=0;ci<5;ci++){Case c;c.n=pre[pos++];c.nt=pre[pos++];c.reps=pre[pos++];c.period={float(pre[pos]),float(pre[pos+1]),float(pre[pos+2])};pos+=3;int L=c.n+1,E=2*c.n+1;auto vf=[&](int n){std::vector<float4>v(n);for(auto&x:v){x={float(pre[pos]),float(pre[pos+1]),float(pre[pos+2]),float(pre[pos+3])};pos+=4;}return v;};c.co=new G<float4>(vf(L),{16384,16384,16384,16384});c.vel=new G<float4>(vf(L),{16384,16384,16384,16384});std::vector<int>nb(L);for(auto&x:nb)x=pre[pos++];c.nb=new G<int>(nb,16384);std::vector<int2>bo(E);for(auto&x:bo){x={int(pre[pos]),int(pre[pos+1])};pos+=2;}c.bonds=new G<int2>(bo,{16384,16384});std::vector<double>l0(E);for(auto&x:l0)x=pre[pos++];c.l0=new G<double>(l0,16384);for(int j=0;j<8;j++){std::vector<float>t(c.nt+1);for(auto&x:t)x=pre[pos++];c.params.push_back(new G<float>(t,16384));}for(int j=0;j<3;j++){std::vector<double>v(L);for(auto&x:v)x=pre[pos++];c.force.push_back(new G<double>(v,16384));}cs.push_back(c);}if(pos!=pre.size())return 3;
 auto launch=[&](Case&c){bond_wlcpowallvisc<<<(c.n+127)/128,128,(c.nt+1)*8*4>>>(c.force[0]->d,c.force[1]->d,c.force[2]->d,c.co->d,c.vel->d,c.nb->d,c.bonds->d,c.l0->d,c.params[0]->d,c.params[1]->d,c.params[2]->d,c.params[3]->d,c.params[4]->d,c.params[5]->d,c.params[6]->d,c.params[7]->d,c.period,1,c.nt,c.n);ck(cudaGetLastError());};for(auto&c:cs){launch(c);ck(cudaDeviceSynchronize());}
 for(int trial=1;trial<=5;trial++){auto art=pre;std::vector<double>times;for(auto&c:cs){for(auto f:c.force){f->reset();f->capture(art);}ck(cudaDeviceSynchronize());auto t=std::chrono::steady_clock::now();for(int it=0;it<c.reps;it++)launch(c);ck(cudaDeviceSynchronize());times.push_back(std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count());for(auto f:c.force)f->capture(art);c.co->capture(art);c.vel->capture(art);c.nb->capture(art);c.bonds->capture(art);c.l0->capture(art);for(auto f:c.params)f->capture(art);}if(art.size()!=pre.size()+gold.size())return 5;bool ok=true;double ma=0;for(size_t i=0;i<gold.size();i++){double x=art[pre.size()+i],e=fabs(x-gold[i]);ok&=std::isfinite(x)&&(kind[i]?x==gold[i]:e<=1e-4+2e-4*fabs(gold[i]));ma=std::max(ma,e);}std::string path=std::string(getenv("STUDY_OUTPUT_DIR")?getenv("STUDY_OUTPUT_DIR"):".")+"/output_trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)art.data(),art.size()*8);f.close();if(!f)return 6;double total=0;for(auto x:times)total+=x;
 printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":null,\"timing_region\":\"sum5_WLC_power_viscous_TEA_force_repeated_accumulation\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"},\"path_times_seconds\":[%.17g,%.17g,%.17g,%.17g,%.17g],\"source_derived_kernel_launches\":12,\"authored_device_kernels\":1}\n",trial,total,ok?"true":"false",art.size(),ma,path.c_str(),art.size(),times[0],times[1],times[2],times[3],times[4]);}
